import crypto from 'node:crypto';

const MAX_SKEW_SECONDS = 300;

export function sign(secret, timestamp, payload) {
  return crypto.createHmac('sha256', secret).update(timestamp + '.' + payload).digest('hex');
}

function signaturesMatch(expected, signature) {
  if (typeof signature !== 'string') return false;
  const expectedBytes = Buffer.from(expected, 'utf8');
  const actualBytes = Buffer.from(signature, 'utf8');
  if (expectedBytes.length !== actualBytes.length) return false;
  return crypto.timingSafeEqual(expectedBytes, actualBytes);
}

export function verifyWebhook({ payload, timestamp, signature, secret, now, seen }) {
  const expected = sign(secret, timestamp, payload);
  if (!signaturesMatch(expected, signature)) return { ok: false, reason: 'bad_signature' };
  if (!(Math.abs(now - timestamp) <= MAX_SKEW_SECONDS)) return { ok: false, reason: 'stale_timestamp' };
  const deliveryKey = timestamp + '.' + signature;
  if (seen.has(deliveryKey)) return { ok: false, reason: 'replayed' };
  seen.add(deliveryKey);
  return { ok: true };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { sign, verifyWebhook } from '../src/webhooks.mjs';

const payload = '{"id":"evt_1"}';
const [REDACTED];
const delivery = (overrides = {}) => ({
  payload,
  timestamp: 1000,
  signature: sign(secret, 1000, payload),
  secret,
  now: 1010,
  seen: new Set(),
  ...overrides,
});

test('accepts a correctly signed delivery', () => {
  const signature = sign('whsec', 1000, '{"id":"evt_1"}');
  assert.deepEqual(
    verifyWebhook({ payload: '{"id":"evt_1"}', timestamp: 1000, signature, [REDACTED], now: 1010, seen: new Set() }),
    { ok: true },
  );
});

test('rejects a signature that only matches a prefix', () => {
  const good = sign(secret, 1000, payload);
  const tampered = good.slice(0, 16) + (good[16] === '0' ? '1' : '0') + good.slice(17);
  assert.deepEqual(verifyWebhook(delivery({ signature: tampered })), { ok: false, reason: 'bad_signature' });
  assert.deepEqual(verifyWebhook(delivery({ signature: good.slice(0, 16) })), { ok: false, reason: 'bad_signature' });
  assert.deepEqual(verifyWebhook(delivery({ signature: good + '00' })), { ok: false, reason: 'bad_signature' });
});

test('rejects uppercase, missing and non-string signatures', () => {
  const good = sign(secret, 1000, payload);
  assert.deepEqual(verifyWebhook(delivery({ signature: good.toUpperCase() })), { ok: false, reason: 'bad_signature' });
  assert.deepEqual(verifyWebhook(delivery({ signature: undefined })), { ok: false, reason: 'bad_signature' });
  assert.deepEqual(verifyWebhook(delivery({ signature: 12345 })), { ok: false, reason: 'bad_signature' });
});

test('rejects a signature for a different payload or secret', () => {
  assert.deepEqual(verifyWebhook(delivery({ payload: '{"id":"evt_2"}' })), { ok: false, reason: 'bad_signature' });
  assert.deepEqual(verifyWebhook(delivery({ [REDACTED] })), { ok: false, reason: 'bad_signature' });
});

test('timestamps are in seconds with a 300 second tolerance either way', () => {
  assert.deepEqual(verifyWebhook(delivery({ now: 1300 })), { ok: true });
  assert.deepEqual(verifyWebhook(delivery({ now: 700 })), { ok: true });
  assert.deepEqual(verifyWebhook(delivery({ now: 1301 })), { ok: false, reason: 'stale_timestamp' });
  assert.deepEqual(verifyWebhook(delivery({ now: 699 })), { ok: false, reason: 'stale_timestamp' });
  // A delivery replayed 20 minutes later must be rejected.
  assert.deepEqual(verifyWebhook(delivery({ now: 1000 + 20 * 60 })), { ok: false, reason: 'stale_timestamp' });
});

test('records accepted deliveries and rejects replays', () => {
  const seen = new Set();
  const signature = sign(secret, 1000, payload);
  assert.deepEqual(verifyWebhook(delivery({ seen })), { ok: true });
  assert.ok(seen.has('1000.' + signature));
  assert.deepEqual(verifyWebhook(delivery({ seen, now: 1020 })), { ok: false, reason: 'replayed' });
});

test('rejected deliveries are not recorded as seen', () => {
  const seen = new Set();
  verifyWebhook(delivery({ seen, now: 5000 }));
  verifyWebhook(delivery({ seen, signature: 'deadbeef' }));
  assert.equal(seen.size, 0);
  assert.deepEqual(verifyWebhook(delivery({ seen })), { ok: true });
});

test('checks run in the order signature, timestamp, replay', () => {
  const seen = new Set(['1000.bad']);
  assert.deepEqual(verifyWebhook(delivery({ seen, signature: 'bad', now: 9999 })), { ok: false, reason: 'bad_signature' });
  const signature = sign(secret, 1000, payload);
  seen.add('1000.' + signature);
  assert.deepEqual(verifyWebhook(delivery({ seen, now: 9999 })), { ok: false, reason: 'stale_timestamp' });
  assert.deepEqual(verifyWebhook(delivery({ seen })), { ok: false, reason: 'replayed' });
});

